CREATE OR REPLACE FUNCTION public.brainia_block_deleted_derived_run()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  payload text;
  lineage_payload text;
  owner_scope text;
  row_id text;
  window_from timestamptz;
  window_to timestamptz;
  blocked boolean := false;
begin
  payload := concat_ws(' ',
    to_jsonb(new)->>'id',
    to_jsonb(new)->>'evidence',
    to_jsonb(new)->>'request',
    to_jsonb(new)->>'response',
    to_jsonb(new)->>'summary',
    to_jsonb(new)->>'query',
    to_jsonb(new)->>'scope',
    to_jsonb(new)->>'objective',
    to_jsonb(new)->>'content',
    to_jsonb(new)->>'checkpoint',
    to_jsonb(new)->>'title',
    to_jsonb(new)->>'explanation'
  );
  -- Lineage is deliberately narrower than the redaction payload: a summary is
  -- not evidence. Only persisted evidence/request/response can carry lineage.
  lineage_payload := concat_ws(' ',
    to_jsonb(new)->>'evidence',
    to_jsonb(new)->>'request',
    to_jsonb(new)->>'response'
  );
  owner_scope := coalesce(to_jsonb(new)->>'owner_id', to_jsonb(new)->>'client_id');
  row_id := to_jsonb(new)->>'id';

  if exists (
    select 1 from deletion_tombstones tombstone
    where tombstone.target_id is not null
      and tombstone.target_id <> coalesce(row_id, '')
      and (owner_scope is null or tombstone.owner_id = owner_scope or tombstone.owner_id = 'anonymous')
      and strpos(payload, tombstone.target_id) > 0
  ) then
    blocked := true;
  end if;

  if not blocked and owner_scope is not null and exists (
    select 1 from raw_events event
    where coalesce(event.owner_id, event.client_id) = owner_scope
      and (event.privacy_status = 'hidden' or not event.processing_allowed)
      and strpos(payload, event.id) > 0
  ) then
    blocked := true;
  end if;

  if not blocked and owner_scope is not null and exists (
    select 1 from entities entity
    where entity.owner_id = owner_scope
      and entity.visibility = 'hidden'
      and strpos(payload, entity.id) > 0
  ) then
    blocked := true;
  end if;

  if not blocked and tg_table_name = 'digest_runs' then
    window_from := nullif(to_jsonb(new)->>'window_from', '')::timestamptz;
    window_to := nullif(to_jsonb(new)->>'window_to', '')::timestamptz;
    if window_from is not null and window_to is not null and exists (
      select 1 from deletion_tombstones tombstone
      join raw_events event on event.id = tombstone.target_id
      where tombstone.target_type = 'event'
        and (owner_scope is null or tombstone.owner_id = owner_scope or tombstone.owner_id = 'anonymous')
        and coalesce(event.timestamp, event.created_at) between window_from and window_to
    ) then
      blocked := true;
    end if;
  end if;

  -- B11 r3 / R2: once the owner has an active tombstone, an inserted derived run
  -- must carry explicit lineage to a still-live event. A summary-only row with
  -- no evidence/query/window lineage can no longer be replayed into serving.
  if tg_op = 'INSERT' and not blocked and exists (
    select 1 from deletion_tombstones tombstone
    where tombstone.owner_id = coalesce(owner_scope, 'anonymous')
  ) and not exists (
    select 1 from raw_events event
    where (
      (owner_scope is not null and coalesce(event.owner_id, event.client_id) = owner_scope)
      or (owner_scope is null and event.owner_id is null and event.client_id is null)
    )
      and event.privacy_status = 'standard'
      and event.processing_allowed
      and strpos(coalesce(lineage_payload, ''), event.id) > 0
  ) then
    return null;
  end if;

  if blocked then
    if tg_op = 'INSERT' then
      return null;
    end if;
    if tg_table_name = 'insight_runs' then
      new.summary := null;
      new.query := null;
      new.evidence := '[]'::jsonb;
      new.response := '{}'::jsonb;
      new.request := '{}'::jsonb;
    elsif tg_table_name = 'digest_runs' then
      new.summary := null;
      new.scope := null;
      new.request := '{}'::jsonb;
      new.response := '{}'::jsonb;
    elsif tg_table_name = 'intelligence_artifacts' then
      new.status := 'stale';
      new.content := null;
      new.evidence := '[]'::jsonb;
      new.checkpoint := '{}'::jsonb;
    elsif tg_table_name = 'insight_candidates' then
      new.status := 'expired';
      new.evidence := '[]'::jsonb;
    end if;
  end if;

  return new;
end;
$function$

objects.function:brainia_block_deleted_event():
CREATE OR REPLACE FUNCTION public.brainia_block_deleted_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if exists (
    select 1 from deletion_tombstones tombstone
    where tombstone.target_type = 'event'
      and tombstone.target_id = new.id
      and (
        tombstone.owner_id = coalesce(new.owner_id, new.client_id)
        or (tombstone.owner_id = 'anonymous' and new.owner_id is null and new.client_id is null)
      )
  ) then
    if tg_op = 'INSERT' then
      return null;
    end if;
    new.privacy_status := 'hidden';
    new.processing_allowed := false;
    new.processing_status := 'discarded';
  end if;
  return new;
end;
$function$

objects.function:brainia_block_event_derived_ins:
CREATE OR REPLACE FUNCTION public.brainia_block_event_derived_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  source_event_id text;
  source_owner_id text;
begin
  -- to_jsonb avoids resolving columns that do not exist on every trigger table.
  source_event_id := case tg_table_name
    when 'financial_transaction_events' then to_jsonb(new)->>'raw_event_id'
    when 'financial_transactions' then to_jsonb(new)->>'anchor_event_id'
    when 'classified_events' then to_jsonb(new)->>'raw_event_id'
    else to_jsonb(new)->>'event_id'
  end;

  if source_event_id is null then
    return new;
  end if;

  source_owner_id := coalesce(to_jsonb(new)->>'owner_id', to_jsonb(new)->>'client_id');

  if exists (
    select 1 from deletion_tombstones tombstone
    where tombstone.target_type = 'event'
      and tombstone.target_id = source_event_id
      and (source_owner_id is null or tombstone.owner_id = source_owner_id)
  ) then
    return null;
  end if;
  return new;
end;
$function$

objects.function:enforce_event_entity_owner():
CREATE OR REPLACE FUNCTION public.enforce_event_entity_owner()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare event_owner text; entity_owner text;
begin
  select owner_id into event_owner from raw_events where id = new.event_id;
  select owner_id into entity_owner from entities where id = new.entity_id;
  if event_owner is not null and entity_owner is not null and event_owner <> entity_owner then
    raise exception 'event_entity_entity_owner_mismatch';
  end if;
  if new.owner_id is null then
    new.owner_id := event_owner;
  elsif event_owner is not null and new.owner_id <> event_owner then
    raise exception 'event_entity_owner_mismatch';
  end if;
  return new;
end $function$

