CREATE OR REPLACE FUNCTION public.enforce_public_taxonomy_owner()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.type in ('domain', 'concept') and new.owner_id is not null then
    raise exception 'public_taxonomy_cannot_be_owned';
  end if;
  return new;
end $function$

objects.function:enforce_relation_owner():
CREATE OR REPLACE FUNCTION public.enforce_relation_owner()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare source_owner text; target_owner text;
begin
  select owner_id into source_owner from entities where id = new.source_entity_id;
  select owner_id into target_owner from entities where id = new.target_entity_id;
  if source_owner is not null and target_owner is not null and source_owner <> target_owner then
    raise exception 'relation_owner_mismatch';
  end if;
  if new.owner_id is null then
    new.owner_id := coalesce(source_owner, target_owner);
  elsif source_owner is not null and new.owner_id <> source_owner then
    raise exception 'relation_owner_mismatch';
  elsif target_owner is not null and new.owner_id <> target_owner then
    raise exception 'relation_owner_mismatch';
  end if;
  return new;
end $function$

objects.function:fx_rates_enforce_approval():
CREATE OR REPLACE FUNCTION public.fx_rates_enforce_approval()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' then
    if old.approved then
      raise exception 'approved fx rate % is immutable and cannot be deleted', old.id;
    end if;
    return old;
  end if;

  if tg_op = 'UPDATE' and old.approved then
    raise exception 'approved fx rate % is immutable and cannot be modified', old.id;
  end if;

  if new.approved and new.approved_at is null then
    new.approved_at := now();
  end if;
  return new;
end
$function$

objects.function:invalidate_intelligence_event():
CREATE OR REPLACE FUNCTION public.invalidate_intelligence_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare affected text;
begin
  if TG_TABLE_NAME = 'raw_events' then affected := OLD.id;
  elsif TG_TABLE_NAME = 'classified_events' then affected := coalesce(NEW.raw_event_id,OLD.raw_event_id);
  else affected := coalesce(NEW.event_id,OLD.event_id); end if;
  update intelligence_artifacts set status='stale',updated_at=now()
    where status in ('ready','insufficient','running') and id in
      (select artifact_id from intelligence_dependencies where event_id=affected);
  if TG_TABLE_NAME='raw_events' then
    if TG_OP='DELETE' or NEW.privacy_status<>'standard' then
      delete from intelligence_confirmations where artifact_id in(select artifact_id from intelligence_dependencies where event_id=affected);
      delete from intelligence_revisions where artifact_id in(select artifact_id from intelligence_dependencies where event_id=affected);
      update intelligence_artifacts set content=null,evidence='[]',checkpoint='{}',status='stale'
        where id in(select artifact_id from intelligence_dependencies where event_id=affected);
      update classification_corrections set revoked_at=now() where event_id=affected and revoked_at is null;
    end if;
  end if;
  return coalesce(NEW,OLD);
end $function$
